pub(crate) fn check_function_grammar<H: CheckHost>(state: &mut CheckState, world: &CheckWorld<'_, '_, '_, '_, '_, '_, '_, '_>, host: &H, gram: &GrammarDef) {
    let named = nikaia_std::block::Text::from(world.words.resolve(gram.name).to_string());
    let mut results: collections::BTreeMap<String, Ty> = collections::BTreeMap::new();
    let mut rules: collections::BTreeSet<String> = collections::BTreeSet::new();
    for rule in gram.rules.iter() {
        rules.insert(nikaia_std::block::Text::from(world.words.resolve(rule.name).to_string()));
        let written: Option<Type> = match rule.ret_type.as_ref() {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        };
        if written.is_some() {
            let one = match written { Some(__nikaia_value) => __nikaia_value, None => continue };
            results.insert(nikaia_std::block::Text::from(world.words.resolve(rule.name).to_string()), host.type_of(&one));
        }
    }
    state.rule_results = results;
    for rule in gram.rules.iter() { for alt in rule.alts.iter() { state.a_name_the_page_does_not_have(world, &alt.pattern); } }
    let streamed = grammar_streamed_rules(world, gram, &state.rule_results, &rules);
    for refused in grammar_emits_undone(world, gram, &streamed) { state.findings.push(refused); }
    for rule in gram.rules.iter() {
        if rule.stream {
            let emitted = grammar_entry_emits(world, gram, world.words.resolve(rule.name), &rules);
            if emitted {
                state.facts.emitting_entries.insert(format!("{}::{}", named, world.words.resolve(rule.name)));
                let mut called: collections::BTreeSet<String> = collections::BTreeSet::new();
                for alt in rule.alts.iter() { grammar_called_rules(world, &alt.pattern.node, &rules, &mut called); }
                for one in called.iter() { if grammar_entry_emits(world, gram, one, &rules) { state.facts.emitting_rules.insert(format!("{}::{}", named, one)); } }
            }
            match grammar_stream_refused(world, rule, &state.rule_results, &rules, emitted) {
                Some(refused) => { state.findings.push(refused); },
                None => { },
            }
        }
        let outer_emitting: Option<Ty> = match state.emitting.as_ref() {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        };
        state.emitting = match *nikaia_std::index::get(&streamed, world.words.resolve(rule.name)) {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        };
        let mut expected: Option<Ty> = None;
        let written: Option<Type> = match rule.ret_type.as_ref() {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        };
        if written.is_some() {
            let one = match written { Some(__nikaia_value) => __nikaia_value, None => continue };
            expected = Some(host.type_of(&one));
        }
        let outer_current: Option<String> = match state.current.as_ref() {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        };
        state.current = Some(format!("{}::{}", named, world.words.resolve(rule.name)));
        let values = state.rule_values(world, host, rule);
        for option in rule.config.iter() {
            let given = check_core_expr(state, world, host, &option.default, &option.default_span);
            state.expect_type(world, &given, &host.type_of(&option.ty), &option.default_span, "argument", &mut |was, wanted| { format!("This default is `{}`, but the option is `{}`.", was, wanted) });
        }
        for alt in rule.alts.iter() {
            let outer_action: Option<String> = match state.inside_an_action.as_ref() {
                Some(__nikaia_it) => Some(__nikaia_it.clone()),
                None => None,
            };
            state.inside_an_action = Some(nikaia_std::block::Text::from(world.words.resolve(rule.name).to_string()));
            state.grammar_values(world, host, gram, &alt.pattern, &rules, values.copy_owned());
            let mut frame = values.copy_owned();
            for bound in state.bindings_of(world, &alt.pattern.node, &rules) { frame.push(bound); }
            state.scope.push(frame.copy_owned());
            check_defaults_folds_in(state, world, host, gram, &alt.pattern.node, &alt.pattern.span);
            state.scope.pop();
            match &alt.action {
                Some(action) => {
                    check_function_action(state, world, host, action, (expected).as_ref(), frame);
                    state.inside_an_action = outer_action;
                },
                None => { state.inside_an_action = outer_action; },
            }
        }
        state.current = outer_current;
        state.emitting = outer_emitting;
    }
}

