pub(crate) fn check_function_action<H: CheckHost>(state: &mut CheckState, world: &CheckWorld<'_, '_, '_, '_, '_, '_, '_, '_>, host: &H, action: &Block, expected: Option<&Ty>, frame: Vec<CheckLocal>) {
    let outer: Option<Ty> = match state.expected.as_ref() {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    };
    state.expected = match expected {
        Some(__nikaia_it) => Some(__nikaia_it.copy_owned()),
        None => None,
    };
    state.scope.push(frame);
    let count = action.stmts.len() as i64;
    let mut tail = check_core_block(state, world, host, action);
    state.scope.pop();
    if expected.is_some() && count > 0 {
        let wanted = nikaia_std::index::or(match expected {
            Some(__nikaia_it) => Some(__nikaia_it.copy_owned()),
            None => None,
        }, || Ty::Unknown);
        let at = nikaia_std::index::get(&action.stmts, nikaia_std::index::at(unsafe { nikaia_std::proven::sub::<i64>(count, 1) })).span;
        match &unsafe { nikaia_std::proven::read(&action.stmts, (nikaia_std::proven::sub::<i64>(count, 1)) as usize) }.node {
            Stmt::Expr(value) => { tail = nikaia_std::index::or(state.text_literal(world, &wanted, value, true), || tail.into()); },
            _ => { },
        }
        state.expect_type(world, &tail, &wanted, &Span { start: at.start, end: at.end }, "returns", &mut |found, want| { format!("This action builds `{}`, but its rule returns `{}`.", found, want) });
        match &unsafe { nikaia_std::proven::read(&action.stmts, (nikaia_std::proven::sub::<i64>(count, 1)) as usize) }.node {
            Stmt::Expr(value) => { check_function_wrap_tail(state, world, host, &tail, &wanted, value, &Span { start: at.start, end: at.end }); },
            _ => { },
        }
    }
    state.expected = outer;
}

pub(crate) fn check_function_first_span(body: &Block) -> Span {
    if body.stmts.is_empty() { return Span::nowhere(); }
    let first = unsafe { nikaia_std::proven::read(&body.stmts, (0) as usize) }.span;
    Span { start: first.start, end: first.end }
}

pub(crate) fn check_function_last_span(body: &Block) -> Option<Span> {
    if body.stmts.is_empty() { return None; }
    let last = unsafe { nikaia_std::proven::read(&body.stmts, (nikaia_std::proven::sub::<i64>(body.stmts.len() as i64, 1)) as usize) }.span;
    Some(Span { start: last.start, end: last.end })
}

pub(crate) fn check_function_is_nullable(ty: &Ty) -> bool { matches!(ty, Ty::Nullable(_)) }

pub(crate) fn check_function_tail_hands_nothing(block: &Block) -> bool {
    if block.stmts.is_empty() { return false; }
    let last = unsafe { nikaia_std::proven::read(&block.stmts, (nikaia_std::proven::sub::<i64>(block.stmts.len() as i64, 1)) as usize) };
    match &last.node {
        Stmt::Expr(value) => check_function_end_hands_nothing(value),
        _ => false,
    }
}

pub(crate) fn check_function_end_hands_nothing(expr: &Expr) -> bool {
    match expr {
        Expr::If { then_branch, else_branch, .. } => match else_branch {
            Some(other) => check_function_tail_hands_nothing(then_branch) || check_function_tail_hands_nothing(other),
            None => true,
        },
        Expr::Block(block, _) => check_function_tail_hands_nothing(block),
        Expr::AsyncGroup(block, _, _, _, _) => check_function_tail_hands_nothing(block),
        _ => false,
    }
}

pub(crate) fn check_function_tail_is_a_value(block: &Block) -> bool {
    if block.stmts.is_empty() { return false; }
    let last = unsafe { nikaia_std::proven::read(&block.stmts, (nikaia_std::proven::sub::<i64>(block.stmts.len() as i64, 1)) as usize) };
    match &last.node {
        Stmt::Expr(value) => check_function_every_end_is_a_value(value),
        Stmt::Return(_) => true,
        Stmt::Break => true,
        Stmt::Continue => true,
        _ => false,
    }
}

pub(crate) fn check_function_every_end_is_a_value(expr: &Expr) -> bool {
    match expr {
        Expr::If { then_branch, else_branch, .. } => {
            if !check_function_tail_is_a_value(then_branch) { return false; }
            return match else_branch {
                Some(other) => check_function_tail_is_a_value(other),
                None => false,
            };
        },
        Expr::Match { arms, .. } => {
            for arm in arms.iter() { if !check_function_every_end_is_a_value(&arm.body) { return false; } }
            return true;
        },
        Expr::Block(block, _) => { return check_function_tail_is_a_value(block); },
        Expr::AsyncGroup(block, _, _, _, _) => { return check_function_tail_is_a_value(block); },
        _ => { return true; },
    }
}

pub(crate) fn check_function_is_branching(expr: &Expr) -> bool {
    match expr {
        Expr::If { .. } => check_function_every_end_is_a_value(expr),
        Expr::Match { .. } => check_function_every_end_is_a_value(expr),
        Expr::Block(_, _) => check_function_every_end_is_a_value(expr),
        Expr::AsyncGroup(_, _, _, _, _) => check_function_every_end_is_a_value(expr),
        _ => false,
    }
}

pub(crate) fn check_function_lends(world: &CheckWorld<'_, '_, '_, '_, '_, '_, '_, '_>, key: &str, at: i64) -> bool {
    let contract = match world.own.functions.get(key) { Some(__nikaia_value) => __nikaia_value, None => return false };
    lends_in_own(contract, at, &vec![world.library])
}

pub(crate) fn check_function_keeps(world: &CheckWorld<'_, '_, '_, '_, '_, '_, '_, '_>, key: &str) -> Vec<String> {
    let contract = match world.own.functions.get(key) { Some(__nikaia_value) => __nikaia_value, None => return vec![] };
    contract.keeps.copy_owned()
}

pub(crate) fn check_function_options_lowered(world: &CheckWorld<'_, '_, '_, '_, '_, '_, '_, '_>, key: &str) -> Vec<ConfigContract> {
    let contract = match world.own.functions.get(key) { Some(__nikaia_value) => __nikaia_value, None => return vec![] };
    lowered_options(contract)
}

