pub(crate) fn check_function_frame<H: CheckHost>(state: &mut CheckState, world: &CheckWorld<'_, '_, '_, '_, '_, '_, '_, '_>, host: &H, receiver: Option<&Receiver>, args: &[FnArg], config: &[ConfigParam], spread: Option<winnow_grammar::Symbol>, target: Option<&str>, key: &str, parameters: &collections::BTreeSet<String>) -> Vec<CheckLocal> {
    let mut frame: Vec<CheckLocal> = vec![];
    let mut offset: i64 = 0;
    if receiver.is_some() {
        offset = 1;
        let mut ty = Ty::Unknown;
        if target.is_some() {
            ty = Ty::Named { name: nikaia_std::index::or(match target {
                Some(__nikaia_it) => Some(nikaia_std::block::Text::from(__nikaia_it.to_string())),
                None => None,
            }, || "".into()), args: state.subject_arguments.copy_owned(), view: nikaia_std::index::or(receiver.as_ref().map(|__nikaia_it| __nikaia_it.is_ref), || false) };
        }
        let id = state.a_new_binding();
        frame.push(CheckLocal::free(String::from("self"), ty, id));
    }
    let mut at: i64 = 0;
    frame.reserve(args.iter().size_hint().0); for arg in args.iter() {
        let name = nikaia_std::block::Text::from(world.words.resolve(arg.name).to_string());
        state.nameable(&name, &arg.span, "a parameter");
        let plain_text = world.words.resolve(arg.ty.name) == "String" && arg.ty.generics.is_empty() && (!arg.ty.is_view || arg.ty.either) && !arg.ty.is_nullable && !arg.ty.is_slice && !arg.mutable;
        let plain_option = arg.ty.is_nullable && !arg.ty.is_view && !arg.ty.is_slice && (*arg.ty.code).is_none() && !arg.mutable;
        let type_parameter = arg.ty.generics.is_empty() && !arg.ty.is_view && !arg.ty.is_nullable && !arg.ty.is_slice && (*arg.ty.code).is_none() && !arg.mutable && state.type_parameters.contains_key(world.words.resolve(arg.ty.name));
        let mut ty = Ty::Unknown;
        if (plain_text || plain_option || type_parameter) && check_function_lends(world, key, unsafe { nikaia_std::proven::add::<i64>(at, offset) }) {
            let mut viewed = arg.ty.clone();
            viewed.is_view = true;
            viewed.either = false;
            ty = check_walked_declared(state, world, &viewed, &arg.span);
        } else { ty = check_walked_declared(state, world, &arg.ty, &arg.span); }
        check_reflected_field_kept(state, world, &arg.ty, &arg.span, true);
        let id = state.a_new_binding();
        state.declared_binding(id, &arg.span, &name);
        let mut local = CheckLocal::free(name, ty.erase(parameters), id);
        if !arg.mutable { local.without_mut = Some(CheckImmutable { at: Span { start: arg.span.start, end: arg.span.end }, kind: CheckKind::Parameter, over: String::from("") }); }
        local.changing = arg.mutable;
        frame.push(local);
        at = unsafe { nikaia_std::proven::add::<i64>(at, 1) };
    }
    for option in config.iter() { check_defaults_a_computed_default(state, world, host, option); }
    let lowered = check_function_options_lowered(world, key);
    frame.reserve(config.iter().size_hint().0); for option in config.iter() {
        let name = nikaia_std::block::Text::from(world.words.resolve(option.name).to_string());
        let mut ty = host.type_of(&option.ty);
        for one in lowered.iter() { if one.name == name && one.ty.is_a_view() { ty = one.ty.clone(); } }
        let id = state.a_new_binding();
        frame.push(CheckLocal::free(name, ty.erase(parameters), id));
    }
    match spread {
        Some(sym) => {
            let id = state.a_new_binding();
            let local = CheckLocal::free(nikaia_std::block::Text::from(world.words.resolve(sym).to_string()), Ty::Unknown, id);
            state.flow.unknown_bound.insert(local.id);
            frame.push(local);
        },
        None => { },
    }
    frame
}

