pub(crate) fn check_function_handed_back<H: CheckHost>(state: &mut CheckState, world: &CheckWorld<'_, '_, '_, '_, '_, '_, '_, '_>, host: &H, body: &Block, expected: Option<&Ty>, tail: &Ty) -> (bool, bool) {
    let mut tail_lent = false;
    let mut tail_view = false;
    if expected.is_none() || body.stmts.is_empty() { return (false, false); }
    let want = nikaia_std::index::or(match expected {
        Some(__nikaia_it) => Some(__nikaia_it.copy_owned()),
        None => None,
    }, || Ty::Unknown);
    let last = unsafe { nikaia_std::proven::read(&body.stmts, (nikaia_std::proven::sub::<i64>(body.stmts.len() as i64, 1)) as usize) };
    let at = Span { start: last.span.start, end: last.span.end };
    match &last.node {
        Stmt::Expr(value) => {
            if !a_body_never_ends(body) {
                let mut plain = false;
                match tail {
                    Ty::Named { name, args, view } => {
                        let view = *view;
                        plain = name == "String" && args.is_empty() && !view;
                    },
                    _ => { },
                }
                tail_lent = state.hands_back_a_view_of_the_subject(world, value) || state.flow.expected_either && plain && state.a_place_of_a_lent_parameter(world, value) || state.a_made_element_lent(world, value, &want);
                if !tail_lent {
                    check_core_a_field_of_a_borrowed_subject(state, world, host, value, &at, "handed back");
                    check_core_a_field_of_a_lent_place_handed_back(state, world, host, value, &at);
                }
                tail_view = state.lent_arms_handed_back(world, value, check_function_is_nullable(&want)) || state.a_get_off_a_lent_parameter(world, value);
                if !tail_lent && !tail_view { check_core_lent_places_in_arms_handed_back(state, world, host, value, &at); }
            }
            state.number_asked(world, value, &want, &at, true);
        },
        _ => { },
    }
    (tail_lent, tail_view)
}

